    version: AI_INTELLIGENCE_VERSION,
    actions: ranked,
    best,
    /* No candidate cleared the floor: say so rather than padding the list. */
    reason: best ? "ok" : activeDays < CONFIDENCE_TARGETS.risk ? "insufficient-data" : "nothing-actionable",
    streak,
