    status: worsened ? "anomaly" : Math.abs(changeRatio) >= threshold ? "shift" : "stable",
    delta: round2(r - b, 3),
    changeRatio: round2(changeRatio, 3),
    direction: changeRatio > 0 ? "up" : changeRatio < 0 ? "down" : "flat",
    confidence,
    band: confidenceBand(confidence),
