        this.sql.exec("UPDATE auth_account_verification_tickets SET state='expired',refresh_cipher='' WHERE ticket_ref=?", input.ticketRef);
        return { error: AUTH_ERROR_CODES.TELEGRAM_VERIFICATION_INVALID };
