        `INSERT INTO auth_sessions(
          session_ref,user_id,created_at,expires_at,last_seen_at,revoked_at,ip_ref,device_ref,user_agent
        ) VALUES(?,?,?,?,?,NULL,?,?,?)`,
        input.sessionRef,
        row.userId,
        input.now,
        input.sessionExpiresAt,
        input.now,
        input.ipRef,
        input.deviceRef,
        input.userAgent
